<main class="cpo-page cpo-stage-admin"><section class="cpo-hero"><div><span class="cpo-eyebrow"><?php echo $langs->trans('InternalTaskBoard'); ?></span><h1><?php echo $langs->trans('InternalTaskManageColumns'); ?></h1><p><?php echo $langs->trans('InternalTaskManageColumnsHelp'); ?></p></div><a class="button" href="board.php"><?php echo $langs->trans('Back'); ?></a></section>
<section class="cpo-panel cpo-stage-create"><div class="cpo-panel-head"><h2><?php echo $langs->trans('InternalTaskAddColumn'); ?></h2></div><form method="post" action="stage_action.php"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="action" value="create"><input type="hidden" name="config_version" value="<?php echo $configVersion; ?>"><div class="cpo-context-grid"><label class="cpo-field"><span><?php echo $langs->trans('InternalTaskColumnCode'); ?></span><input required pattern="[a-z0-9_]{1,64}" maxlength="64" name="code"></label><label class="cpo-field"><span>English</span><input required maxlength="255" name="label_en"></label><label class="cpo-field"><span>العربية</span><input required dir="rtl" maxlength="255" name="label_ar"></label><label class="cpo-field"><span>中文</span><input required maxlength="255" name="label_zh"></label><label class="cpo-field"><span><?php echo $langs->trans('Color'); ?></span><input required type="color" name="color" value="#2980b9"></label></div><button class="button button-save"><?php echo $langs->trans('InternalTaskAddColumn'); ?></button></form></section>
<section class="cpo-stage-list" aria-label="<?php echo $langs->trans('InternalTaskManageColumns'); ?>"><?php foreach($stages as $stage){$locked=(int)$stage['is_system']===1;$inUse=false;$res=$db->query('SELECT rowid FROM '.MAIN_DB_PREFIX.'cpo_task WHERE entity='.(int)$conf->entity.' AND fk_stage='.(int)$stage['rowid']." AND status<>'deleted' LIMIT 1");if($res&&$db->fetch_object($res))$inUse=true; ?><article class="cpo-panel cpo-stage-admin-card<?php echo !$stage['active']?' is-inactive':''; ?>" style="--cpo-stage-color:<?php echo dol_escape_htmltag($stage['color']); ?>"><header><span class="cpo-stage-swatch" aria-hidden="true"></span><div><strong><bdi><?php echo dol_escape_htmltag($stage['code']); ?></bdi></strong><small><?php echo $locked?$langs->trans('InternalTaskColumnLocked'):$langs->trans('InternalTaskCustomColumn'); ?> · <?php echo $inUse?$langs->trans('InternalTaskColumnInUse'):$langs->trans('InternalTaskColumnUnused'); ?></small></div></header><form method="post" action="stage_action.php"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="action" value="update"><input type="hidden" name="stage_id" value="<?php echo (int)$stage['rowid']; ?>"><input type="hidden" name="version" value="<?php echo (int)$stage['version']; ?>"><div class="cpo-context-grid"><label class="cpo-field"><span>English</span><input required maxlength="255" name="label_en" value="<?php echo dol_escape_htmltag($stage['label_en']); ?>"></label><label class="cpo-field"><span>العربية</span><input required dir="rtl" maxlength="255" name="label_ar" value="<?php echo dol_escape_htmltag($stage['label_ar']); ?>"></label><label class="cpo-field"><span>中文</span><input required maxlength="255" name="label_zh" value="<?php echo dol_escape_htmltag($stage['label_zh']); ?>"></label><label class="cpo-field"><span><?php echo $langs->trans('Color'); ?></span><input required type="color" name="color" value="<?php echo dol_escape_htmltag($stage['color']); ?>"></label></div><button class="button"><?php echo $langs->trans('Save'); ?></button></form><?php if($stage['behavior']==='work'&&(int)$stage['active']===1){ ?><form class="cpo-stage-order-actions" method="post" action="stage_action.php"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="action" value="reorder"><input type="hidden" name="config_version" value="<?php echo $configVersion; ?>"><input type="hidden" name="move_id" value="<?php echo (int)$stage['rowid']; ?>"><?php foreach($workIds as $id){ ?><input type="hidden" name="stage_ids[]" value="<?php echo $id; ?>"><?php } ?><button class="button" name="direction" value="up" aria-label="<?php echo $langs->trans('InternalTaskMoveColumnUp'); ?>">↑ <?php echo $langs->trans('InternalTaskMoveColumnUp'); ?></button><button class="button" name="direction" value="down" aria-label="<?php echo $langs->trans('InternalTaskMoveColumnDown'); ?>">↓ <?php echo $langs->trans('InternalTaskMoveColumnDown'); ?></button></form><?php } ?><?php if(!$locked){ ?><form method="post" action="stage_action.php"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="stage_id" value="<?php echo (int)$stage['rowid']; ?>"><input type="hidden" name="version" value="<?php echo (int)$stage['version']; ?>"><input type="hidden" name="config_version" value="<?php echo $configVersion; ?>"><input type="hidden" name="active" value="<?php echo $stage['active']?0:1; ?>"><button class="button"<?php echo $stage['active']&&$inUse?' disabled title="'.dol_escape_htmltag($langs->trans('InternalTaskCannotDeactivateInUse')).'"':''; ?>><?php echo $langs->trans($stage['active']?'Disable':'Enable'); ?></button></form><?php } ?></article><?php } ?></section></main>
